def find_factors(n):
    factors = []
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            factors.append(i)
            if i != n // i:
                factors.append(n // i)
    return sorted(factors)

def generate_partitions(n, factors, start=0):
    if n == 1:
        return [[]]
    partitions = []
    for i in range(start, len(factors)):
        factor = factors[i]
        if n % factor == 0:
            for partition in generate_partitions(n // factor, factors, i):
                partitions.append([factor] + partition)
    return partitions

def sort_partitions(partitions):
    return sorted(partitions, key=lambda x: (x[0], x[1] if len(x) > 1 else float('inf')))

def count_partitions(partitions):
    return len(partitions)

def prod_int_part(n):
    if n < 2:
        return [0, []]
    factors = find_factors(n)
    partitions = generate_partitions(n, factors)
    sorted_partitions = sort_partitions(partitions)
    max_length = max(len(part) for part in sorted_partitions)
    result_partitions = [part for part in sorted_partitions if len(part) == max_length]
    return [count_partitions(result_partitions), result_partitions[0]]

