def watch_pyramid_from_the_side(characters):
    if not characters:
        return ""
    height = len(characters)
    pyramid_side = []
    for i in range(height):
        row = " " * (height - i - 1) + characters[i] * (2 * i + 1)
        pyramid_side.append(row)
    return "\n".join(pyramid_side)


def watch_pyramid_from_above(characters):
    if not characters:
        return ""
    height = len(characters)
    pyramid_above = []
    for i in range(height):
        row = "".join(characters[j] if j >= i else " " for j in range(height))
        pyramid_above.append(row)
    return "\n".join(pyramid_above)


