def calculate_vat(price):
    """Helper function to calculate VAT based on the given price."""
    vat_rate = 0.15
    return price * vat_rate

def excluding_vat_price(price):
    """Entrypoint function to calculate the original price excluding VAT."""
    if price is None:
        return -1
    vat_amount = calculate_vat(price)
    original_price = price - vat_amount
    return round(original_price, 2)

